use page_window::page;

#[test]
fn offsets_at_or_past_the_end_yield_empty_pages() {
    let items = [10, 20, 30];
    assert!(page(&items, 3, 2).is_empty());
    assert!(page(&items, 4, 1).is_empty());
    assert!(page(&items, usize::MAX, 2).is_empty());
    assert!(page::<i32>(&[], 1, 1).is_empty());
}

#[test]
fn huge_limits_do_not_overflow_and_return_the_tail() {
    let items = [10, 20, 30, 40];
    assert_eq!(page(&items, 1, usize::MAX), &[20, 30, 40]);
    assert_eq!(page(&items, 0, usize::MAX), &items[..]);
}
